def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    can_fit = bins >= item
    ratio = np.where(can_fit, item / bins, 0)
    return np.where(can_fit, -ratio, -np.inf)
